async function gerarEmail(nome,empresa,setor,grupo,angulo,tom,hist){
  if(!getClaudeKey()){return {assunto:"⚠ Configure a Claude API Key em ⚙ Configurações",corpo:"Clique no botão ⚙ no canto superior direito e insira sua chave sk-ant-..."};}
  const assinatura=ASSINATURAS[grupo.id]||("Pedro Ica\nHead of Growth | "+grupo.name);
  const prompt=`${grupo.prompt}\n\nEscreva um email de prospecção B2B para ${empresa} do setor ${setor}.\nÂNGULO: ${angulo}\nTOM: ${tom}\n${nome?"DESTINATÁRIO: "+nome+"\n":""}${hist?"HISTÓRICO: "+hist+"\n":""}DOR IDENTIFICADA: ${grupo.dor(setor)}\n\nREGRAS: primeira linha específica sobre ${empresa}, conectar a dor ao que ${grupo.name} faz, benchmark do setor ${setor}, CTA de 20 min, máximo 180 palavras.\nUSE OBRIGATORIAMENTE esta assinatura no final:\n${assinatura}\nRetorne APENAS JSON sem markdown: {"assunto":"...","corpo":"..."}`;
  try{
    const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json","x-api-key":getClaudeKey(),"anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:900,messages:[{role:"user",content:prompt}]})});
    const d=await r.json();
    if(d.error){return {assunto:"Erro API: "+d.error.type,corpo:d.error.message||""};}
    const txt=(d.content&&d.content[0]&&d.content[0].text)||"{}";
    try { return JSON.parse(txt.replace(/```json|```/g,"").trim()); }
    catch(e) { return {assunto:"Email gerado",corpo:txt}; }
  }catch(e){return {assunto:"Erro de conexão",corpo:"Verifique sua API key e conexão com a internet. "+e.message};}
}
async function gerarIntel(empresa,setor,grupo,decs,hist){
  if(!getClaudeKey()){return "⚠ Configure a Claude API Key em ⚙ Configurações para usar esta funcionalidade.";}
  const prompt=`Você é analista de inteligência comercial para ${grupo.name} (${grupo.desc}).\nEMPRESA: ${empresa} | SETOR: ${setor}\nDECISORES: ${decs||"nenhum"}\nHISTÓRICO: ${hist||"nenhuma atividade"}\n\nGere análise estratégica em parágrafos fluidos (sem bullets) cobrindo: diagnóstico de fit com ${grupo.name}, recomendação baseada no histórico, serviço com maior chance de abrir porta e insight de timing do setor ${setor}. Máximo 200 palavras.`;
  try{
    const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json","x-api-key":getClaudeKey(),"anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:700,messages:[{role:"user",content:prompt}]})});
    const d=await r.json();
    if(d.error){return "Erro API: "+d.error.type+" — "+d.error.message;}
    return(d.content&&d.content[0]&&d.content[0].text)||"Sem resposta da API.";
  }catch(e){return "Erro de conexão: "+e.message;}
}
async function gerarAlertas(empresa,setor,grupo){
  if(!getClaudeKey()){return [];}
  const prompt=`Simule 3 alertas de inteligência de mercado sobre ${empresa} (setor ${setor}) relevantes para ${grupo.name}. JSON sem markdown: [{"title":"...","desc":"...","urgency":"new"}]`;
  try{
    const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json","x-api-key":getClaudeKey(),"anthropic-version":"2023-06-01","anthropic-dangerous-direct-browser-access":"true"},body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:500,messages:[{role:"user",content:prompt}]})});
    const d=await r.json();
    if(d.error){return [];}
    try{return JSON.parse((d.content&&d.content[0]&&d.content[0].text||"[]").replace(/```json|```/g,"").trim());}catch{return[];}
  }catch(e){return [];}
}

function fitColor(f){return f==="alto"?"#00FF94":f==="medio"?"#FFB547":"#FF4757";}
function fitLabel(f){return f==="alto"?"FIT ALTO":f==="medio"?"FIT MED":"SEM FIT";}
function initials(name){return(name||"?").split(" ").slice(0,2).map(w=>w[0]).join("").toUpperCase();}
function loadSt(k,def){try{const v=localStorage.getItem(k);return v?JSON.parse(v):def;}catch{return def;}}
function saveSt(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch(e){if(e.name==='QuotaExceededError'||e.code===22){console.error('[CRM] localStorage cheio — dado não salvo:',k);alert('⚠️ Armazenamento local cheio. Exporte um backup (🛟 Ferramentas) e limpe dados antigos para continuar salvando.');}}}
function hexRgb(h){const m=h.replace("#","").match(/.{2}/g);return m?m.map(x=>parseInt(x,16)).join(","):"255,255,255";}
